"""Client for the list endpoints of the Tidewater Freight API."""

import json
import time
from collections.abc import Callable
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime
from typing import NamedTuple

MAX_LIMIT = 500  # largest `limit` the list endpoints accept (tidewater-pagination, PG-5824)
MAX_ATTEMPTS = 4  # first attempt plus 3 retries on 429/503 (tidewater-rate-limits)


class Response(NamedTuple):
    status: int
    headers: dict[str, str]
    body: bytes


# Sends one GET request for `path` with these query parameters and returns the response.
Transport = Callable[[str, dict[str, str]], Response]


class ApiError(Exception):
    def __init__(self, status: int, code: str):
        super().__init__(f"{status} {code}")
        self.status = status
        self.code = code


def _utcnow() -> datetime:
    return datetime.now(timezone.utc)


def _error_code(r: Response) -> str:
    try:
        return str(json.loads(r.body)["error"]["code"])
    except (ValueError, KeyError, TypeError):
        return ""


def _header(headers: dict[str, str], name: str) -> str | None:
    for k, v in headers.items():
        if k.lower() == name:
            return v
    return None


def _retry_wait(r: Response, now: Callable[[], datetime]) -> float:
    """Seconds to wait before retrying a 429/503 response."""
    fallback = 2.0 if r.status == 503 else 1.0
    value = _header(r.headers, "retry-after")
    if value is None:
        return fallback
    value = value.strip()
    if value.isascii() and value.isdigit():
        return float(int(value))
    try:
        when = parsedate_to_datetime(value)
    except (TypeError, ValueError):
        return fallback
    if when is None:
        return fallback
    if when.tzinfo is None:
        when = when.replace(tzinfo=timezone.utc)
    return max(0.0, (when - now()).total_seconds())


def _send(transport, path, params, sleep, now) -> Response:
    for attempt in range(1, MAX_ATTEMPTS + 1):
        r = transport(path, dict(params))
        if r.status == 200:
            return r
        if r.status in (429, 503) and attempt < MAX_ATTEMPTS:
            wait = _retry_wait(r, now)
            if wait > 0:
                sleep(wait)
            continue
        raise ApiError(r.status, _error_code(r))
    raise AssertionError("unreachable")


def list_all(
    transport: Transport,
    resource: str,
    filters: dict[str, str] | None = None,
    page_size: int | None = None,
    sleep: Callable[[float], None] = time.sleep,
    now: Callable[[], datetime] = _utcnow,
) -> list[dict]:
    """Every item of the `resource` list endpoint that matches `filters`, in the order the API returns them.

    `page_size` is the number of items to ask for per request. None asks for the largest page
    the API accepts, and a value above that maximum is sent as the maximum.
    Every wait goes through `sleep(seconds)`; `now()` returns the current time, timezone-aware UTC.
    Raises ApiError with the response's status and error code when the API answers with an
    error the client does not retry, or when the retries allowed for a request run out.
    """
    limit = str(MAX_LIMIT if page_size is None else min(page_size, MAX_LIMIT))
    path = f"/v2/{resource}"
    # Filters go on the first request only; later requests carry just the cursor.
    params = dict(filters or {})
    params["limit"] = limit
    out: list[dict] = []
    while True:
        r = _send(transport, path, params, sleep, now)
        page = json.loads(r.body)
        out += page["data"]
        if not page.get("has_more"):
            return out
        params = {"cursor": page["next_cursor"], "limit": limit}
